INSERT OR IGNORE INTO ft_content (id, author_id, title, content, slug, summary, cover_img, cover_alt, type, status, published_at, created_at, updated_at) VALUES
('30000000-0000-4000-8000-000000000001', '99999999-0000-4000-8000-000000000000', 'Por que um teste vocacional muda sua trajetória profissional', '<p>Decidir uma carreira com base em informações confiáveis é o primeiro passo para um trabalho que faz sentido. Entenda como um teste vocacional bem construído ajuda.</p>', 'por-que-teste-vocacional-muda-trajetoria', 'Como a orientação vocacional baseada em dados evita escolhas por impulso e aproxima você do trabalho ideal.', '/illustrations/career-development.svg', 'Ilustração de desenvolvimento de carreira com degraus ascendentes', 'blog', 'published', '2026-07-24T12:00:00Z', datetime('now'), datetime('now')),
('30000000-0000-4000-8000-000000000002', '99999999-0000-4000-8000-000000000000', 'Explorando profissões do futuro: tendências para os próximos anos', '<p>Carreiras em tecnologia, saúde, energia e educação estão em transformação. Conheça as áreas em alta e as habilidades que serão exigidas.</p>', 'explorando-profissoes-do-futuro', 'Um panorama das profissões em crescimento e das habilidades transversais que o mercado passará a exigir.', '/illustrations/brainstorming.svg', 'Ilustração de brainstorming com ideias em formato de lâmpadas', 'blog', 'published', '2026-07-17T12:00:00Z', datetime('now'), datetime('now')),
('30000000-0000-4000-8000-000000000003', '99999999-0000-4000-8000-000000000000', 'Habilidades que valem mais que o diploma no mercado atual', '<p>Comunicação, pensamento crítico e adaptabilidade: as competências comportamentais ganham espaço nas seleções e definem crescimento profissional.</p>', 'habilidades-que-valem-mais-que-diploma', 'As competências que o mercado valoriza hoje e como desenvolvê-las enquanto você constrói sua carreira.', '/illustrations/informed-decision.svg', 'Ilustração de tomada de decisão informada', 'blog', 'published', '2026-07-10T12:00:00Z', datetime('now'), datetime('now')),
('30000000-0000-4000-8000-000000000004', '99999999-0000-4000-8000-000000000000', 'Primeiro emprego: do currículo à entrevista, sem atropelos', '<p>Buscar o primeiro emprego exige método: currículo ajustado, preparação para entrevista e entendimento real da vaga.</p>', 'primeiro-emprego-curriculo-a-entrevista', 'Um roteiro prático para quem está começando: como se preparar para a busca do primeiro trabalho.', '/illustrations/job-hunt.svg', 'Ilustração de busca de emprego com currículo', 'blog', 'published', '2026-07-03T12:00:00Z', datetime('now'), datetime('now')),
('30000000-0000-4000-8000-000000000005', '99999999-0000-4000-8000-000000000000', 'Metas profissionais: transformando objetivos em plano', '<p>Objetivos profissionais só se realizam quando viram plano. Aprenda a estruturar metas de curto e médio prazo com passos concretos.</p>', 'metas-profissionais-objetivos-em-plano', 'Como converter aspirações de carreira em um plano de ação realista, com marcos e avaliação periódica.', '/illustrations/personal-goals.svg', 'Ilustração de objetivos pessoais com alvo', 'blog', 'published', '2026-06-26T12:00:00Z', datetime('now'), datetime('now')),
('30000000-0000-4000-8000-000000000006', '99999999-0000-4000-8000-000000000000', 'Mudança de carreira: quando e como fazer a transição', '<p>Mudar de área é um dos movimentos mais desafiadores da vida profissional. Saiba avaliar o momento, reduzir riscos e planejar a transição.</p>', 'mudanca-de-carreira-como-fazer-transicao', 'Um guia para quem considera migrar de área: autoconhecimento, habilidades transferíveis e planejamento da transição.', '/illustrations/career-development.svg', 'Ilustração de transição de carreira com novo caminho', 'blog', 'published', '2026-06-19T12:00:00Z', datetime('now'), datetime('now'));
